CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `HumanResources_vEmployeeDepartmentHistory` AS select `e`.`BusinessEntityID` AS `BusinessEntityID`,`p`.`Title` AS `Title`,`p`.`FirstName` AS `FirstName`,`p`.`MiddleName` AS `MiddleName`,`p`.`LastName` AS `LastName`,`p`.`Suffix` AS `Suffix`,`s`.`Name` AS `Shift`,`d`.`Name` AS `Department`,`d`.`GroupName` AS `GroupName`,`edh`.`StartDate` AS `StartDate`,`edh`.`EndDate` AS `EndDate` from ((((`HumanResources_Employee` `e` join `Person_Person` `p` on(`p`.`BusinessEntityID` = `e`.`BusinessEntityID`)) join `HumanResources_EmployeeDepartmentHistory` `edh` on(`e`.`BusinessEntityID` = `edh`.`BusinessEntityID`)) join `HumanResources_Department` `d` on(`edh`.`DepartmentID` = `d`.`DepartmentID`)) join `HumanResources_Shift` `s` on(`s`.`ShiftID` = `edh`.`ShiftID`));
